{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "transformer",
    "window": 3,
    "threshold_q": 0.9999,
    "persistence": 5
  },
  "intent_understood_as": "minimize_false_alarms",
  "reason": "Intent demands minimal false alarms while keeping real attack detection. Transformer avoids catastrophic per-attack failures and has the lowest DNS delay (10.9s) among supervised models. Using q=0.9999 (most conservative threshold) with persistence=5 maximally suppresses false alarms. Temporal replay shows transformer at default already achieves 0.01 false alarms/hour; this configuration will drive that even lower while maintaining genuine DNS detection."
}
